DEFAULT_NAME = 'BarrierWatcher'
_PAGE_CACHE: dict = {}


def rebrand(document: str, name: str | None = None) -> str:
    """Put the operator's chosen system name into a page, escaped."""
    clean = ' '.join(name.split()) if isinstance(name, str) and name.strip() else DEFAULT_NAME
    safe = html.escape(clean, quote=True)
    return (document.replace('__SYSTEM_NAME__', safe)
            .replace('__SYSTEM_INITIAL__', html.escape(clean[0].upper()))
            .replace('C500 GUARD', html.escape(clean.upper(), quote=True)).replace('C500 Guard', safe))


def dashboard_page(name: str | None = None) -> str:
    key = name or DEFAULT_NAME
    page = _PAGE_CACHE.get(key)
    if page is None:
        page = rebrand(PAGE_TEMPLATE.replace('__MAX_POLYGON_CORNERS__', str(MAX_POLYGON_CORNERS)), key)
        _PAGE_CACHE.clear()
        _PAGE_CACHE[key] = page
    return page


PAGE = dashboard_page()


